import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 270005;
    static int m, n, k, mod;
    static int[][] f = new int[19][MAXN];
    static List<Long> g = new ArrayList<>();
    static int[] cnt = new int[MAXN];
    static int[] factorial = new int[MAXN];
    static int[] invFactorial = new int[MAXN];

    static int normalize(int x) {
        if (x < 0) return x + mod;
        if (x >= mod) return x - mod;
        return x;
    }

    static void add_value(int[] x, int y) {
        for (int i = 0; i < x.length; i++) {
            x[i] = normalize(x[i] + y);
        }
    }

    static int power(int base, int exp) {
        int result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (int) ((long) result * base % mod);
            base = (int) ((long) base * base % mod);
            exp >>= 1;
        }
        return result;
    }

    static void initialize(int n) {
        factorial[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorial[i] = (int) ((long) factorial[i - 1] * i % mod);
        }
        invFactorial[n] = power(factorial[n], mod - 2);
        for (int i = n - 1; i >= 0; i--) {
            invFactorial[i] = (int) ((long) invFactorial[i + 1] * (i + 1) % mod);
        }
    }

    static void transform(int[] f, int size, int h) {
        for (int p = 1; p < size; p <<= 1) {
            for (int i = 0; i < size; i += p << 1) {
                for (int k = i; k < i + p; k++) {
                    f[k + p] = normalize(f[k + p] + h * f[k]);
                }
            }
        }
    }

    static List<Long> multiplySeries(List<Long> A, List<Long> B, int l) {
        List<Long> C = new ArrayList<>(Collections.nCopies(l + 1, 0L));
        for (int i = 0; i <= l; i++) {
            for (int j = 0; j <= l - i; j++) {
                C.set(i + j, C.get(i + j) + A.get(i) * B.get(j));
            }
        }
        for (int i = 0; i <= l; i++) {
            C.set(i, C.get(i) % mod);
        }
        return C;
    }

    static List<Long> powerSeries(List<Long> A, int k, int l) {
        List<Long> C = new ArrayList<>(Collections.nCopies(l + 1, 0L));
        C.set(0, 1L);
        while (k > 0) {
            if ((k & 1) == 1) {
                C = multiplySeries(C, A, l);
            }
            A = multiplySeries(A, A, l);
            k >>= 1;
        }
        return C;
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextInt();
        mod = sc.nextInt();

        initialize(n);
        if ((n & 1) == 1) {
            System.out.println(power(k, n));
            return;
        }

        m = 1;
        while (m <= n) m <<= 1;
        int l = 0;
        for (int i = 0; i < 20; i++) {
            for (int j = 0; j < MAXN; j++) {
                f[i][j] = 0;
            }
        }

        // Compute cnt array
        for (int i = 0; i < m; i++) {
            cnt[i] = (i >> 1) + (i & 1);
        }

        initialize(m);
        for (int i = 0; i < m; i++) {
            f[cnt[i]][i] = invFactorial[i];
        }

        for (int i = 0; i <= 19; i++) {
            transform(f[i], m, 1);
        }

        g = new ArrayList<>(Collections.nCopies(l + 1, 0L));
        for (int s = 0; s < m; s++) {
            for (int i = 0; i <= l; i++) {
                g.set(i, (long) f[i][s]);
            }
            g = powerSeries(g, k, l);
            for (int i = 0; i <= l; i++) {
                f[i][s] = g.get(i).intValue();
            }
        }

        // Transform back with -1
        transform(f[cnt[n]], m, -1);

        long result = normalize((int) ((power(k, n) - 1L * f[cnt[n]][n] * factorial[n] % mod)));
        System.out.println(result);
    }
    static int normalize(int x) {
        if (x < 0) return x + mod;
        if (x >= mod) return x - mod;
        return x;
    }
}

